{
  "meta": {
    "name": "CRM",
    "description": "A CRM application with user authentication, contact management, a dashboard, role-based access for admins and members, and a premium plan with payment processing and analytics for admins."
  },
  "entities": [
    {
      "name": "Contact",
      "ownable": true,
      "fields": [
        {
          "name": "firstName",
          "type": "string",
          "required": true
        },
        {
          "name": "lastName",
          "type": "string",
          "required": true
        },
        {
          "name": "email",
          "type": "email",
          "required": true,
          "unique": true
        },
        {
          "name": "phone",
          "type": "string"
        },
        {
          "name": "company",
          "type": "string"
        },
        {
          "name": "status",
          "type": "enum",
          "enumValues": [
            "lead",
            "active",
            "inactive"
          ],
          "default": "lead"
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "admin",
      "description": "Administrator with full access"
    },
    {
      "name": "member",
      "description": "Standard user",
      "isDefault": true
    }
  ],
  "permissions": [
    {
      "role": "member",
      "entity": "Contact",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "own"
    },
    {
      "role": "admin",
      "entity": "Contact",
      "actions": [
        "create",
        "read",
        "update",
        "delete"
      ],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Contacts",
      "route": "/contacts",
      "type": "list",
      "entity": "Contact",
      "access": [
        "member",
        "admin"
      ]
    },
    {
      "name": "New Contact",
      "route": "/contacts/new",
      "type": "form",
      "entity": "Contact",
      "access": [
        "member",
        "admin"
      ]
    },
    {
      "name": "Dashboard",
      "route": "/dashboard",
      "type": "dashboard",
      "access": [
        "member",
        "admin"
      ],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Contacts",
          "entity": "Contact",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Analytics",
      "route": "/analytics",
      "type": "dashboard",
      "access": [
        "admin"
      ],
      "requiresPlan": "premium",
      "widgets": [
        {
          "type": "stat",
          "label": "Total Contacts",
          "entity": "Contact",
          "metric": "count"
        },
        {
          "type": "chart",
          "label": "Contacts by Status",
          "entity": "Contact",
          "field": "status",
          "metric": "count"
        }
      ]
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": []
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": [
        "analytics"
      ]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumAnalyticsGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": [
          "Analytics"
        ],
        "features": [
          "analytics"
        ]
      }
    },
    {
      "type": "ownership",
      "id": "contactOwnership",
      "entity": "Contact"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
